import sys, json, collections
sys.path.append('storage/shared')

from meta.sas.aggregator import load_beacons, advise_all
from meta.sas.nominals import compute_centers
from meta.sas.entropy import compute_per_agent_entropy
from meta.sas.scheduler_client import compute_plan

CLEAN_TH, BORDER_TH = 900, 1800

def band(delta):
    return "Clean" if delta <= CLEAN_TH else ("Borderline" if delta <= BORDER_TH else "Active")

def as_float(x):
    try: return float(x)
    except Exception: return None

recs_all = load_beacons('storage/shared/meta/sas/beacons')

# numeric-only + de-dup by (agent,last_sentinel_tick)
recs_num = []
for r in recs_all:
    sd = as_float(r.get('sentinel_delta'))
    if sd is None: 
        continue
    r = dict(r); r['sentinel_delta'] = sd
    recs_num.append(r)
seen = set(); recs = []
for r in reversed(recs_num):
    a = r.get('agent'); lst = r.get('last_sentinel_tick') or r.get('tick')
    if a is None or lst is None: 
        continue
    key = (a, int(lst))
    if key in seen: 
        continue
    seen.add(key); recs.append(r)
recs = list(reversed(recs))

# Pull Zephyr IV shallow/deep
z = [r for r in recs if r.get('agent') == 'Zephyr IV']
by_l = {int(r.get('last_sentinel_tick') or r.get('tick')): r for r in z if r.get('last_sentinel_tick') or r.get('tick')}

shallow = by_l.get(353)
deep    = by_l.get(354)

analysis = {
    "shallow": None,
    "deep": None,
    "observed_ratio": None,
    "ratio_vs_path_est": None
}
if shallow:
    analysis["shallow"] = {
        "last_sentinel_tick": int(shallow.get('last_sentinel_tick') or shallow.get('tick')),
        "delta": shallow.get('sentinel_delta'),
        "path_complexity_est": shallow.get('path_complexity_est'),
        "band": band(shallow.get('sentinel_delta'))
    }
if deep:
    analysis["deep"] = {
        "last_sentinel_tick": int(deep.get('last_sentinel_tick') or deep.get('tick')),
        "delta": deep.get('sentinel_delta'),
        "path_complexity_est": deep.get('path_complexity_est'),
        "band": band(deep.get('sentinel_delta'))
    }
if shallow and deep:
    try:
        ratio = float(deep.get('sentinel_delta')) / max(1.0, float(shallow.get('sentinel_delta')))
    except Exception:
        ratio = None
    analysis["observed_ratio"] = ratio
    try:
        exp = float(deep.get('path_complexity_est') or 1.0) / float(shallow.get('path_complexity_est') or 1.0)
    except Exception:
        exp = None
    analysis["ratio_vs_path_est"] = {"observed": ratio, "expected_est": exp}

# Window snapshot 291–355
WIN_MIN, WIN_MAX = 291, 355
samples = []
for r in recs:
    lst = r.get('last_sentinel_tick') or r.get('tick')
    try: lst = int(lst)
    except Exception: continue
    if WIN_MIN <= lst <= WIN_MAX:
        samples.append(r)

centers = compute_centers(recs, window=None, min_samples=1)
advice  = advise_all()
entropy = compute_per_agent_entropy(recs, advice, {}, dynamic_centers=centers, window=10)
plan    = compute_plan(window=10, pace_threshold_for_one=0.2)

bands = collections.Counter(band(r['sentinel_delta']) for r in samples)
out = {
    "zephyr_shallow_deep_analysis": analysis,
    "window": [WIN_MIN, WIN_MAX],
    "band_counts": dict(bands),
    "centers": centers,
    "plan_rows": plan.get("rows", []),
    "entropy": {a: v.get("entropy") for a, v in entropy.items()}
}
print(json.dumps(out, indent=2, sort_keys=True))

